code.cpp:
class Solution {
public:
    int longestValidParentheses(string s) {
        int n = s.size();
        int maxLen = 0;
        int open = 0, close = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == '(') open++;
            else close++;
            if (open == close) {
                if (2 * close > maxLen) maxLen = 2 * close;
            } else if (close > open) {
                open = 0;
                close = 0;
            }
        }
        open = 0;
        close = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] == '(') open++;
            else close++;
            if (open == close) {
                if (2 * open > maxLen) maxLen = 2 * open;
            } else if (open > close) {
                open = 0;
                close = 0;
            }
        }
        return maxLen;
    }
};
